def _restore_promoted(
    output: Path,
    roles: list[dict[str, Any]],
    promoted: list[str],
    agent_baseline: dict[str, Any],
    machine_baseline: dict[str, Any],
) -> None:
    by_name = {role["name"]: role for role in roles}
    for name in reversed(promoted):
        role = by_name[name]
        if role["kind"] == "file":
            _restore_file(output, role)
        elif name == "agent-index-note":
            current = _current_agent(output / role["path"], role["selector"])
            _commit_agent(output / role["path"], role["selector"], current, agent_baseline)
        else:
            current = _current_machine(output / role["path"], role["selector"])
            _commit_machine(output / role["path"], role["selector"], current, machine_baseline)

def _promotion(
    output: Path,
    manifest_path: Path,
    manifest: dict[str, Any],
    roles: list[dict[str, Any]],
    fault: str | None,
) -> dict[str, Any]:
    by_name = {role["name"]: role for role in roles}
    agent_role = by_name["agent-index-note"]
    machine_role = by_name["machine-knowledge-note"]
    agent_baseline = json_load(Path(agent_role["baseline"]["backup"]))
    agent_candidate = json_load(Path(agent_role["modified"]["candidate"]))
    machine_baseline = json_load(Path(machine_role["baseline"]["backup"]))
    machine_candidate = json_load(Path(machine_role["modified"]["candidate"]))
    sidecars = {
        role["name"]: {
            suffix: Path(str(output / role["path"]) + suffix).exists() for suffix in ("-wal", "-shm", "-journal")
        }
        for role in (agent_role, machine_role)
    }
    promoted: list[str] = []
    manifest["status"] = "promoting"
    json_write(manifest_path, manifest)
    try:
        for role in roles:
            if role["kind"] == "file":
                _promote_file(output, role, role["baseline"]["sha256"])
            elif role["name"] == "agent-index-note":
                _commit_agent(output / role["path"], role["selector"], agent_baseline, agent_candidate)
            else:
                _commit_machine(output / role["path"], role["selector"], machine_baseline, machine_candidate)
            promoted.append(role["name"])
            if fault == f"after-{role['name']}":
                raise CkbError(f"injected record replace promotion failure after {role['name']}")
        verification_errors = _verify_roles(output, roles, "modified")
        note_errors = audit_notes(output)
        record_audit = audit_work_record_index(output)
        agent_audit = audit_agent_index(output)
        if verification_errors or note_errors or record_audit["status"] != "passed" or agent_audit["status"] != "passed":
            raise CkbError(
                "record replace post-promotion verification failed: "
                f"roles={verification_errors[:5]}; notes={note_errors[:5]}; records={record_audit['errors'][:5]}; "
                f"agent={agent_audit['errors'][:5]}"
            )
        manifest.update(
            {
                "status": "completed",
                "completed_at_utc": utc_now(),
                "verification": {
                    "status": "passed",
                    "role_errors": [],
                    "note_errors": [],
                    "work_record_index": record_audit,
                    "agent_index": agent_audit,
                },
            }
        )
        json_write(manifest_path, manifest)
        journal = record_operation(output, "record", "record:replace", "replaced", [_journal_evidence(output, manifest_path)])
        manifest["operation_journal"] = journal
        json_write(manifest_path, manifest)
        return journal
    except Exception:
        _restore_promoted(output, roles, promoted, agent_baseline, machine_baseline)
        restored_errors = _verify_roles(output, roles, "baseline")
        manifest.update(
            {
                "status": "failed-restored" if not restored_errors else "failed-restore-incomplete",
                "failed_at_utc": utc_now(),
                "promoted_before_failure": promoted,
                "restore_errors": restored_errors,
            }
        )
        json_write(manifest_path, manifest)
        if restored_errors:
            raise CkbError(f"record replace failed and baseline restoration was incomplete: {restored_errors[:10]}")
        raise
    finally:
        _cleanup_new_sqlite_sidecars(output / agent_role["path"], sidecars[agent_role["name"]])
        _cleanup_new_sqlite_sidecars(output / machine_role["path"], sidecars[machine_role["name"]])

def _load_rollback_manifest(output: Path, manifest_path: Path) -> dict[str, Any]:
    manifest_path = manifest_path.resolve()
    root = _operation_root(output)
    try:
        manifest_path.relative_to(root)
    except ValueError as exc:
        raise CkbError(f"record rollback manifest must be inside this OUTPUT: {manifest_path}") from exc
    if not manifest_path.is_file():
        raise CkbError(f"record rollback manifest is missing: {manifest_path}")
    manifest = json_load(manifest_path)
    if manifest.get("schema_version") != RECORD_REPLACE_SCHEMA_VERSION or manifest.get("operation") != "record-replace":
        raise CkbError(f"unsupported record rollback manifest: {manifest_path}")
    if Path(str(manifest.get("output") or "")).resolve() != output.resolve():
        raise CkbError(f"record rollback manifest OUTPUT differs from the requested OUTPUT: {manifest_path}")
    if manifest.get("status") not in {"completed", "rolled-back"}:
        raise CkbError(f"record rollback requires a completed replacement: status={manifest.get('status')}")
    return manifest

def rollback_replacement(output: Path, manifest_path: Path) -> dict[str, Any]:
    """Restore the exact file and SQLite logical state owned by one replacement."""

    output = output.resolve()
    manifest_path = manifest_path.resolve()
    with _replace_lock(output):
        manifest = _load_rollback_manifest(output, manifest_path)
        roles = list(manifest.get("roles") or [])
        if {role.get("name") for role in roles} != set(_FILE_ROLES) | {"agent-index-note", "machine-knowledge-note"}:
            raise CkbError("record rollback manifest role set is incomplete")
        baseline_errors = _verify_roles(output, roles, "baseline")
        if manifest["status"] == "rolled-back":
            if baseline_errors:
                raise CkbError(f"record rollback baseline drifted after the prior rollback: {baseline_errors[:10]}")
            journal = record_operation(output, "record", "record:rollback", "rolled-back", [_journal_evidence(output, manifest_path)])
            return {
                "schema_version": RECORD_REPLACE_SCHEMA_VERSION,
                "status": "rolled-back",
                "idempotent": True,
                "operation_id": manifest["operation_id"],
                "manifest": str(manifest_path),
                "restored_roles": [role["name"] for role in roles],
                "operation_journal": journal,
                "operation_journal_recorded": True,
            }
        modified_errors = _verify_roles(output, roles, "modified")
        if modified_errors:
            if not baseline_errors:
                manifest["status"] = "rolled-back"
                manifest["rolled_back_at_utc"] = manifest.get("rolled_back_at_utc") or utc_now()
                json_write(manifest_path, manifest)
                journal = record_operation(output, "record", "record:rollback", "rolled-back", [_journal_evidence(output, manifest_path)])
                return {
                    "schema_version": RECORD_REPLACE_SCHEMA_VERSION,
                    "status": "rolled-back",
                    "idempotent": True,
                    "operation_id": manifest["operation_id"],
                    "manifest": str(manifest_path),
                    "restored_roles": [role["name"] for role in roles],
                    "operation_journal": journal,
                    "operation_journal_recorded": True,
                }
            try:
                record_operation(output, "record", "record:rollback", "conflict", [_journal_evidence(output, manifest_path)])
            except CkbError:
                pass
            raise CkbError(f"record rollback conflict: replacement-owned objects drifted: {modified_errors[:10]}")
        by_name = {role["name"]: role for role in roles}
        restored: list[str] = []
        try:
            for role in reversed(roles):
                if role["kind"] == "file":
                    _restore_file(output, role)
                elif role["name"] == "agent-index-note":
                    _commit_agent(
                        output / role["path"],
                        role["selector"],
                        json_load(Path(role["modified"]["candidate"])),
                        json_load(Path(role["baseline"]["backup"])),
                    )
                else:
                    _commit_machine(
                        output / role["path"],
                        role["selector"],
                        json_load(Path(role["modified"]["candidate"])),
                        json_load(Path(role["baseline"]["backup"])),
                    )
                restored.append(role["name"])
            errors = _verify_roles(output, roles, "baseline")
            note_errors = audit_notes(output)
            records = audit_work_record_index(output)
            agent = audit_agent_index(output)
            if errors or note_errors or records["status"] != "passed" or agent["status"] != "passed":
                raise CkbError(
                    f"record rollback verification failed: roles={errors[:5]}; notes={note_errors[:5]}; "
                    f"records={records['errors'][:5]}; agent={agent['errors'][:5]}"
                )
        except Exception as exc:
            compensation_errors: list[dict[str, Any]] = []
            for name in reversed(restored):
                role = by_name[name]
                try:
                    if role["kind"] == "file":
                        _promote_file(output, role, role["baseline"]["sha256"])
                    elif role["name"] == "agent-index-note":
                        _commit_agent(
                            output / role["path"],
                            role["selector"],
                            json_load(Path(role["baseline"]["backup"])),
                            json_load(Path(role["modified"]["candidate"])),
                        )
                    else:
                        _commit_machine(
                            output / role["path"],
                            role["selector"],
                            json_load(Path(role["baseline"]["backup"])),
                            json_load(Path(role["modified"]["candidate"])),
                        )
                except Exception as compensation_exc:
                    compensation_errors.append(
                        {"role": name, "type": type(compensation_exc).__name__, "message": str(compensation_exc)}
                    )
            manifest["rollback_failure"] = {
                "type": type(exc).__name__,
                "message": str(exc),
                "restored_before_failure": restored,
                "compensation_errors": compensation_errors,
            }
            json_write(manifest_path, manifest)
            try:
                record_operation(output, "record", "record:rollback", "failed", [_journal_evidence(output, manifest_path)])
            except CkbError:
                pass
            if isinstance(exc, CkbError):
                raise
            raise CkbError(f"record rollback failed: {exc}") from exc
        manifest.update(
            {
                "status": "rolled-back",
                "rolled_back_at_utc": utc_now(),
                "rollback_verification": {
                    "status": "passed",
                    "role_errors": [],
                    "note_errors": [],
                    "work_record_index": records,
                    "agent_index": agent,
                },
            }
        )
        json_write(manifest_path, manifest)
        journal = record_operation(output, "record", "record:rollback", "rolled-back", [_journal_evidence(output, manifest_path)])
        manifest["rollback_operation_journal"] = journal
        json_write(manifest_path, manifest)
        return {
            "schema_version": RECORD_REPLACE_SCHEMA_VERSION,
            "status": "rolled-back",
            "idempotent": False,
            "operation_id": manifest["operation_id"],
            "manifest": str(manifest_path),
            "restored_roles": [role["name"] for role in roles],
            "operation_journal": journal,
            "operation_journal_recorded": True,
        }

def page_tag(page_type: str) -> str:
    if page_type == "boundary":
        return "#类型/边界"
    if page_type in {"repository", "module"}:
        return "#类型/职责"
    return "#类型/代码"

def _markdown_root(output: Path) -> Path:
    root = output / "markdown"
    if not (root / "projection.json").is_file():
        raise CkbError(f"Markdown projection is required before recording knowledge notes: {root}")
    return root

def _resolve_page_titles(output: Path, selectors: list[str], query_record: Path | None) -> list[str]:
    projection = json_load(output / "markdown/projection.json")
    pages = projection.get("pages", [])
    title_by_id = {page["id"]: page["title"] for page in pages}
    titles = set(title_by_id.values())
    folded = {title.casefold(): title for title in titles}
    selected: list[str] = []
    for selector in selectors:
        exact = folded.get(selector.casefold())
        if exact:
            selected.append(exact)
            continue
        partial = sorted(title for title in titles if selector.casefold() in title.casefold())
        if len(partial) != 1:
            raise CkbError(f"knowledge-page selector must match one page: {selector}; candidates={partial[:20]}")
        selected.append(partial[0])
    if query_record:
        query = json_load(query_record)
        for page in query.get("selected_pages", []):
            title = page.get("title")
            if title in titles:
                selected.append(title)
        owners = projection.get("entity_owner_pages", {})
        for node in query.get("nodes", []):
            node_id = node.get("id")
            page_id = owners.get(node_id) or (node_id if node_id in title_by_id else None)
            if page_id in title_by_id:
                selected.append(title_by_id[page_id])
        for entity in query.get("selected_entities", []):
            title = entity.get("human_page_title")
            if title in titles:
                selected.append(title)
    return list(dict.fromkeys(selected))

def _source_links_for_titles(output: Path, titles: list[str]) -> list[str]:
    projection = json_load(output / "markdown/projection.json")
    graph = json_load(output / "graph.json")
    page_by_title = {page["title"]: page for page in projection.get("pages", [])}
    entity_by_id = {entity["id"]: entity for entity in graph.get("entities", [])}
    state = json_load(output / "state.json")
    snapshot = state.get("source_snapshot") or {}
    openers = ensure_local_openers(
        output,
        Path(state["repository"]["root"]),
        Path(snapshot["root"]) if snapshot.get("root") else None,
    )
    links = []
    for title in titles:
        page = page_by_title.get(title)
        entity = entity_by_id.get(page.get("id")) if page else None
        if not entity or not entity.get("path") or not entity.get("range"):
            continue
        links.append(
            source_markdown_link(
                openers,
                entity["path"],
                int(entity["range"]["start_line"]),
                int(entity["range"]["end_line"]),
            )
        )
    return links

def read_note_body(body_path: Path) -> str:
    """Read and validate one user-authored knowledge-note body."""

    if not body_path.is_file():
        raise CkbError(f"note body does not exist: {body_path}")
    try:
        body = body_path.read_text(encoding="utf-8-sig").strip()
    except UnicodeDecodeError as exc:
        raise CkbError(f"note body must be valid UTF-8: {exc}") from exc
    if not body:
        raise CkbError("note body must not be empty")
    if not contains_chinese_narrative(body):
        raise CkbError("knowledge note descriptions must use Simplified Chinese; English proper nouns and code identifiers are allowed")
    if body.startswith("---\n") or LONG_HEX.search(body):
        raise CkbError("human knowledge notes must omit frontmatter and hash-like identifiers")
    return body

def render_note_text(kind: str, title: str, body: str, linked_titles: list[str], source_links: list[str]) -> str:
    sections = [f"# {title.strip()}", "", f"标签：{TAG_BY_KIND[kind]}", "", body]
    if linked_titles:
        sections.extend(["", "## 相关知识页", "", *[f"- [[{value}]]" for value in linked_titles]])
    if source_links:
        sections.extend(["", "## 源码入口", "", *[f"- {value}" for value in source_links]])
    text = "\n".join(sections).rstrip() + "\n"
    if LONG_HEX.search(text):
        raise CkbError("generated human knowledge note contains a hash-like identifier")
    return text

def selectors_for_changed_paths(output: Path, changed_paths: list[str]) -> list[str]:
    """Map working-tree paths to deterministic owner pages, with repository fallback."""
    selected_paths = {value.replace("\\", "/") for value in changed_paths}
    if not selected_paths:
        return []
    projection = json_load(output / "markdown/projection.json")
    graph = json_load(output / "graph.json")
    title_by_id = {page["id"]: page["title"] for page in projection.get("pages", [])}
    owners = projection.get("entity_owner_pages", {})
    selectors: list[str] = []
    for entity in graph.get("entities", []):
        if str(entity.get("path", "")).replace("\\", "/") in selected_paths:
            owner = owners.get(entity["id"]) or (entity["id"] if entity["id"] in title_by_id else None)
            if owner in title_by_id:
                selectors.append(title_by_id[owner])
    selectors = list(dict.fromkeys(selectors))
    if selectors:
        return selectors
    repository_pages = [
        page["title"]
        for page in projection.get("pages", [])
        if page.get("page_type") == "repository"
    ]
    return repository_pages[:1]

def audit_notes(output: Path) -> list[dict[str, Any]]:
    root = output / "markdown"
    if not root.is_dir():
        return [{"reason": "markdown-vault-missing"}]
    projection = json_load(root / "projection.json")
    titles = {page["title"] for page in projection.get("pages", [])}
    notes = []
    errors: list[dict[str, Any]] = []
    for kind, directory_name in DIRECTORY_BY_KIND.items():
        directory = root / directory_name
        if not directory.is_dir():
            errors.append({"reason": "note-directory-missing", "directory": directory_name})
            continue
        for path in sorted(directory.glob("*.md")):
            text = path.read_text(encoding="utf-8")
            note_title = text.splitlines()[0].removeprefix("# ").strip() if text else ""
            notes.append(note_title)
            expected_tag = TAG_BY_KIND[kind]
            tags = re.findall(r"#类型/[\w\u3400-\u9fff-]+", text)
            if tags != [expected_tag]:
                errors.append({"reason": "note-tag-invalid", "path": str(path), "tags": tags, "expected": expected_tag})
            if text.startswith("---\n"):
                errors.append({"reason": "note-frontmatter-visible", "path": str(path)})
            if LONG_HEX.search(text):
                errors.append({"reason": "note-hash-visible", "path": str(path)})
            narrative = "\n".join(
                line
                for line in text.splitlines()
                if not line.startswith(("#", "标签：", "- [[", "- [打开源码："))
            )
            if not contains_chinese_narrative(narrative):
                errors.append({"reason": "note-description-not-chinese", "path": str(path)})
    all_titles = titles | set(notes)
    for directory_name in NOTE_DIRECTORIES:
        for path in (root / directory_name).glob("*.md"):
            text = path.read_text(encoding="utf-8")
            for target in re.findall(r"\[\[([^\]|#]+)", text):
                if target not in all_titles:
                    errors.append({"reason": "note-link-dangling", "path": str(path), "target": target})
    return errors

def workspace_status(output: Path) -> dict[str, Any]:
    state = json_load(output / "state.json")
    overlay = output / "workspace-meta/working-overlay.json"
    return {
        "schema_version": 1,
        "status": "ready",
        "baseline": {
            "status": (state.get("source_snapshot") or {}).get("status", "legacy-live-worktree"),
            "commit": state["repository"]["commit"],
            "snapshot_root": (state.get("source_snapshot") or {}).get("root"),
        },
        "working_overlay": json_load(overlay) if overlay.is_file() else {"status": "not-synced"},
        "notes": {"status": "passed" if not audit_notes(output) else "failed"} if (output / "markdown/projection.json").is_file() else {"status": "waiting-for-markdown"},
    }
